        function colorizeSequence(seq) {
            let html = "";
            for(let i=0; i<seq.length; i++) {
                let aa = seq[i].toUpperCase();
                html += `<span class="aa-${aa}">${seq[i]}</span>`;
            }
            return html;
        }

        function parseFasta(fastaData) {
            let lines = fastaData.split('\n');
            let seqs = [];
            let currentId = "";
            let currentSeq = "";

            for(let i=0; i<lines.length; i++) {
                let line = lines[i].trim();
                if(line.startsWith(">")) {
                    if(currentId !== "") {
                        seqs.push({id: currentId, seq: currentSeq});
                    }
                    currentId = line.substring(1);
                    currentSeq = "";
                } else if(line.length > 0) {
                    currentSeq += line;
                }
            }
            if(currentId !== "") {
                seqs.push({id: currentId, seq: currentSeq});
            }
            return seqs;
        }

        function renderAlignment(fastaData) {
            let container = document.getElementById("msa-container");
            container.innerHTML = "";

            let seqs = parseFasta(fastaData);
            if(seqs.length === 0) {
                container.innerHTML = "<span style='color:red;'>Failed to parse FASTA data.</span>";
                return;
            }

            let html = "";
            for(let i=0; i<seqs.length; i++) {
                html += `<div class="seq-row">
                            <span class="seq-id" title="${seqs[i].id}">${seqs[i].id}</span>
                            <span class="seq-data">${colorizeSequence(seqs[i].seq)}</span>
                         </div>`;
            }
            container.innerHTML = html;
            document.getElementById('status').innerText = `Loaded ${seqs.length} sequences.`;
        }

        function loadAlignment() {
            var file = document.getElementById("cluster-select").value;
            document.getElementById('status').innerText = 'Fetching ' + file + '...';

            fetch(file + '?t=' + new Date().getTime())
                .then(response => {
                    if (!response.ok) throw new Error("HTTP error " + response.status);
                    return response.text();
                })
                .then(text => renderAlignment(text))
                .catch(err => {
                    console.error(err);
                    document.getElementById('status').innerText = 'Failed to load alignment.';
                });
        }

        window.onload = loadAlignment;
    </script>
</body>
</html>
