    "id": "anton-1-gff_pseudogene_translator",
    "version": "1.0.0",
    "name": "GFF Pseudogene Extractor & Translator (1 Core)",
    "container": "python:3.11-slim",
    "help": "### What it does
This tool is designed to recover and characterize degraded or pseudogenized gene loci (specifically optimized for hyper-variable multigene families like PIR/VIR) from genomic annotations.

It operates in three distinct phases:
1. **Coordinate Identification:** Parses a GFF3 file for any `pseudogenic_transcript` features and maps their constituent `exon` coordinate segments.
2. **Sequence Extraction:** Extracts the corresponding genomic nucleotide sequences from the reference genome FASTA, merges exons in coordinate order, and reverse-complements minus-strand transcripts.
3. **Six-Frame Translation:** Translates the stitched transcript sequences in all six standard genetic reading frames. It retains stop codons as `*` to capture full pseudogene translation profiles and filters out any translated fragments shorter than the user-specified minimum length threshold.

### Inputs
* **GFF3 Annotation file:** Gene annotations containing `pseudogenic_transcript` and child `exon` coordinates.
* **Genome FASTA file:** Genomic nucleotide sequences corresponding to the chromosome/scaffold IDs in the GFF3.
* **Minimum translated fragment length:** Amino acid length cutoff (defaults to 50) below which translations are discarded.

### Outputs
* **FASTA:** An amino acid FASTA file containing all translated reading frames passing the length filter.",
    "inputs": [
      {
        "name": "gff",
        "type": "data",
        "label": "GFF3 Annotation file"
      },
      {
        "name": "genome",
        "type": "data",
        "label": "Genome FASTA file"
      },
      {
        "name": "min_len",
        "type": "integer",
        "label": "Minimum translated fragment length",
        "value": 50
      }
    ],
    "outputs": [
      {
        "name": "fasta",
        "type": "data",
        "format": "fasta",
        "label": "Six-frame translated pseudogenes"
      }
    ],
    "shell_command": "cat << 'EOF' > translate.py
import sys
from collections import defaultdict

def read_fasta(path):
    seqs = {}
    cur, buf = None, []
    with open(path) as f:
        for line in f:
            if line.startswith(">"):
                if cur: seqs[cur] = "".join(buf)
                cur = line[1:].split()[0]; buf = []
            else: buf.append(line.strip())
        if cur: seqs[cur] = "".join(buf)
    return seqs

def revcomp(seq):
    tab = str.maketrans("ACGTacgtNn", "TGCAtgcaNn")
    return seq.translate(tab)[::-1]

CODON_TABLE = {
    "TTT":"F","TTC":"F","TTA":"L","TTG":"L","CTT":"L","CTC":"L","CTA":"L","CTG":"L",
    "ATT":"I","ATC":"I","ATA":"I","ATG":"M","GTT":"V","GTC":"V","GTA":"V","GTG":"V",
    "TCT":"S","TCC":"S","TCA":"S","TCG":"S","CCT":"P","CCC":"P","CCA":"P","CCG":"P",
    "ACT":"T","ACC":"T","ACA":"T","ACG":"T","GCT":"A","GCC":"A","GCA":"A","GCG":"A",
    "TAT":"Y","TAC":"Y","TAA":"*","TAG":"*","CAT":"H","CAC":"H","CAA":"Q","CAG":"Q",
    "AAT":"N","AAC":"N","AAA":"K","AAG":"K","GAT":"D","GAC":"D","GAA":"E","GAG":"E",
    "TGT":"C","TGC":"C","TGA":"*","TGG":"W","CGT":"R","CGC":"R","CGA":"R","CGG":"R",
    "AGT":"S","AGC":"S","AGA":"R","AGG":"R","GGT":"G","GGC":"G","GGA":"G","GGG":"G"
}

def translate(seq, frame=0):
    seq = seq[frame:]
    return "".join(CODON_TABLE.get(seq[i:i+3].upper(), "X") for i in range(0, len(seq)-2, 3))

def parse_pseudogene_exons(gff):
    exon_of_tx = defaultdict(list)
    pseudo_tx_ids = set()
    with open(gff) as f:
        for line in f:
            if line.startswith("#"): continue
            cols = line.rstrip().split("\t")
            if len(cols) < 9: continue
            ftype = cols[2]
            attrs = dict(kv.split("=",1) for kv in cols[8].split(";") if "=" in kv)
            if ftype == "pseudogenic_transcript":
                tx_id = attrs.get("ID","")
                pseudo_tx_ids.add(tx_id)
                exon_of_tx[tx_id].append((cols[0], int(cols[3]), int(cols[4]), cols[6]))
            elif ftype == "exon":
                parent = attrs.get("Parent","")
                if parent in pseudo_tx_ids:
                    exon_of_tx[parent].append((cols[0], int(cols[3]), int(cols[4]), cols[6]))
    return exon_of_tx

gff_path, nuc_path, min_len_val, out_path = sys.argv[1], sys.argv[2], int(sys.argv[3]), sys.argv[4]

exon_of_tx = parse_pseudogene_exons(gff_path)
nuc = read_fasta(nuc_path)
out_recs = []
for tx_id, exons in exon_of_tx.items():
    chroms = set(e[0] for e in exons)
    if len(chroms) != 1: continue
    chrom, strand = exons[0][0], exons[0][3]
    if chrom not in nuc: continue

    exons_sorted = sorted(set(exons), key=lambda e: e[1])
    seq_parts = [nuc[chrom][s-1:e] for _, s, e, _ in exons_sorted]
    cds = "".join(seq_parts)
    if strand == "-": cds = revcomp(cds)

    # 6-frame translation
    for frame in range(3):
        aa = translate(cds, frame=frame)
        if len(aa) >= min_len_val: out_recs.append(f">{tx_id}_frame+{frame}\n{aa}\n")
    rc = revcomp(cds)
    for frame in range(3):
        aa = translate(rc, frame=frame)
        if len(aa) >= min_len_val: out_recs.append(f">{tx_id}_frame-{frame}\n{aa}\n")

with open(out_path, "w") as out:
    out.write("".join(out_recs))
EOF
python3 translate.py "$(inputs.gff.path)" "$(inputs.genome.path)" "$(inputs.min_len)" "$(outputs.fasta.path)""
  }
}

