import os
import bioblend.galaxy
import time

url = os.environ.get("GALAXY_URL")
key = os.environ.get("GALAXY_API_KEY")

gi = bioblend.galaxy.GalaxyInstance(url=url, key=key)
history_id = "bbd44e69cb8906b5c0a92f1d9b046fdd"

# Let's find the newly added datasets in the history (they will be at the end, having highest HIDs)
# Polling loop
completed = {}
start_time = time.time()
timeout = 300 # 5 minutes

print("Polling native Galaxy UDT jobs...")
while len(completed) < 2 and (time.time() - start_time) < timeout:
    contents = gi.histories.show_history(history_id, contents=True, order="hid-dsc")
    # Look for our newly created dataset outputs by the UDT (their name should match or be 'Six-frame translated pseudogenes' etc.)
    udt_datasets = [d for d in contents if d["history_content_type"] == "dataset" and "six-frame translated" in d["name"].lower()]

    for d in udt_datasets:
        # Since we ran two jobs, we will have two datasets
        did = d["id"]
        if did in completed: continue

        # Get full state
        det = gi.datasets.show_dataset(did)
        state = det["state"]
        name = det["name"]
        print(f"  Dataset '{name}' | ID: {did} | State: {state}")

        if state in ("ok", "finished"):
            completed[did] = det
            print(f"    SUCCESS! Dataset '{name}' is complete!")
        elif state in ("error", "failed"):
            completed[did] = det
            print(f"    FAILED! Dataset '{name}' failed. Details: {det.get('misc_info')}")

    if len(completed) < 2:
        time.sleep(10)

if len(completed) == 2:
    print("\nBoth native UDT runs completed! Let's verify output sizes.")
    for did, det in completed.items():
        # Count translations inside the fasta natively
        content = gi.datasets.download_dataset(did).decode("utf-8")
        n_seqs = sum(1 for line in content.splitlines() if line.startswith(">"))
        print(f"  - Dataset: {det['name']} | HDA ID: {did} | Total translations: {n_seqs}")
else:
    print("\nTimeout reached while polling!")
PYEOF"}}}
