from pathlib import Path
from collections import defaultdict
import hashlib, os

def read_fasta(path):
    seqs = {}
    cur, buf = None, []
    with open(path) as f:
        for line in f:
            if line.startswith('>'):
                if cur: seqs[cur] = ''.join(buf)
                cur = line[1:].split()[0]
                buf = []
            else:
                buf.append(line.strip())
        if cur: seqs[cur] = ''.join(buf)
    return seqs

def revcomp(seq):
    return seq.translate(str.maketrans('ACGTacgtNn','TGCAtgcaNn'))[::-1]
CODON_TABLE = {
    'TTT':'F','TTC':'F','TTA':'L','TTG':'L','CTT':'L','CTC':'L','CTA':'L','CTG':'L',
    'ATT':'I','ATC':'I','ATA':'I','ATG':'M','GTT':'V','GTC':'V','GTA':'V','GTG':'V',
    'TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P',
    'ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A',
    'TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q',
    'AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E',
    'TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
    'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'
}
def translate(seq, frame=0):
    seq=seq[frame:]
    return ''.join(CODON_TABLE.get(seq[i:i+3].upper(),'X') for i in range(0,len(seq)-2,3))
def parse_pseudogene_exons(gff):
    exon_of_tx=defaultdict(list); pseudo_tx_ids=set()
    with open(gff) as f:
        for line in f:
            if line.startswith('#'): continue
            cols=line.rstrip().split('\t')
            if len(cols)<9: continue
            attrs=dict(kv.split('=',1) for kv in cols[8].split(';') if '=' in kv)
            if cols[2]=='pseudogenic_transcript':
                tx_id=attrs.get('ID',''); pseudo_tx_ids.add(tx_id)
                exon_of_tx[tx_id].append((cols[0], int(cols[3]), int(cols[4]), cols[6]))
            elif cols[2]=='exon':
                parent=attrs.get('Parent','')
                if parent in pseudo_tx_ids:
                    exon_of_tx[parent].append((cols[0], int(cols[3]), int(cols[4]), cols[6]))
    return exon_of_tx

def generate(g, gff_path, nuc_path, out_path):
    exon_of_tx=parse_pseudogene_exons(gff_path); nuc=read_fasta(nuc_path); out=[]
    for tx_id, exons in exon_of_tx.items():
        chroms={e[0] for e in exons}
        if len(chroms)!=1: continue
        chrom, strand=exons[0][0], exons[0][3]
        if chrom not in nuc: continue
        exons_sorted=sorted(set(exons), key=lambda e: (e[1], e[2], e[0], e[3]))
        cds=''.join(nuc[chrom][s-1:e] for _,s,e,_ in exons_sorted)
        if strand=='-': cds=revcomp(cds)
        for frame in range(3):
            aa=translate(cds, frame)
            if len(aa)>=50: out.append(f'>{tx_id}_frame+{frame}\n{aa}\n')
        rc=revcomp(cds)
        for frame in range(3):
            aa=translate(rc, frame)
            if len(aa)>=50: out.append(f'>{tx_id}_frame-{frame}\n{aa}\n')
    Path(out_path).write_text(''.join(out))

for g,gff,nuc in [
    ('PvP01','data/genomes/gff/PvivaxP01.gff','data/genomes/nuc/PvivaxP01_genome.fasta'),
    ('PvPAM','data/genomes/gff/PvivaxPAM.gff','data/genomes/nuc/PvivaxPAM_genome.fasta')]:
    out=f'data/pseudogenes/tmp_{g}_deterministic.fasta'
    generate(g,gff,nuc,out)
    local=f'data/pseudogenes/{g}_pseudo_translations.fasta'
    b1=Path(local).read_bytes(); b2=Path(out).read_bytes()
    print(g, 'local_md5', hashlib.md5(b1).hexdigest(), 'det_md5', hashlib.md5(b2).hexdigest(), 'same', b1==b2,
          'seqs', sum(1 for l in b2.splitlines() if l.startswith(b'>')))
