import os, json, requests, time
from bioblend.galaxy import GalaxyInstance
url=os.environ['GALAXY_URL'].rstrip('/'); key=os.environ['GALAXY_API_KEY']
headers={'x-api-key':key,'Content-Type':'application/json'}
gi=GalaxyInstance(url=url, key=key)
history_id='bbd44e69cb8906b5c0a92f1d9b046fdd'
# Current Step 5 output HIDs 80-84; all from one job. Use HID 80 dataset to get creating job.
current_outputs=['f9cad7b01a4721352f6733a6a39755d3','f9cad7b01a472135b85d07d0bb9e894c','f9cad7b01a472135b1315e3d499fda8f','f9cad7b01a4721358be8c9f558220cb8','f9cad7b01a47213533cb7f1d8f79381f']
job_ids=set()
for did in current_outputs:
    ds=gi.datasets.show_dataset(did)
    print('output', ds.get('hid'), did, ds.get('state'), ds.get('name'), 'job', ds.get('creating_job'))
    if ds.get('creating_job'):
        job_ids.add(ds['creating_job'])
print('job_ids', job_ids)
for jid in job_ids:
    # Try common Galaxy cancel endpoint forms.
    for method, endpoint, payload in [
        ('PUT', f'/api/jobs/{jid}', {'state':'deleted'}),
        ('DELETE', f'/api/jobs/{jid}', None),
        ('PUT', f'/api/jobs/{jid}/cancel', {}),
    ]:
        try:
            if method=='PUT':
                r=requests.put(url+endpoint, headers=headers, json=payload, timeout=30)
            elif method=='DELETE':
                r=requests.delete(url+endpoint, headers=headers, timeout=30)
            print(method, endpoint, '->', r.status_code, r.text[:500])
            if r.status_code in (200,202,204):
                break
        except Exception as e:
            print(method, endpoint, 'ERR', repr(e))
    try:
        j=gi.jobs.show_job(jid)
        print('after cancel job', jid, j.get('state'))
    except Exception as e:
        print('show job err', repr(e))
