cd /Users/anton/.loom/analyses/phist2
.loom/env/bin/python3 <<'PY'
import os, json, requests
url=os.environ['GALAXY_URL'].rstrip('/'); key=os.environ['GALAXY_API_KEY']
headers={'x-api-key':key,'Content-Type':'application/json'}

shell = r'''set -euo pipefail
threads="$(inputs.threads)"
mkdir -p prostt5_weights tmp
cp "$(inputs.prostt5_model.path)" prostt5_weights/prostt5-f16.gguf

echo "Foldseek version:" > foldseek.log
foldseek version >> foldseek.log 2>&1 || true
echo "Threads: $threads" >> foldseek.log
echo "GPU flag: --gpu 1" >> foldseek.log
echo "Summary generator: awk/sort; no Python dependency" >> foldseek.log

foldseek easy-cluster \
  "$(inputs.seqs.path)" \
  vir_struct_cluster \
  tmp \
  --prostt5-model prostt5_weights \
  -c "$(inputs.coverage)" \
  -e "$(inputs.evalue)" \
  --alignment-type "$(inputs.alignment_type)" \
  --gpu 1 \
  --threads "$threads" >> foldseek.log 2>&1

awk -F '\t' '
function genome(pid) {
    if (pid ~ /^PVP01/) return "PvP01";
    if (pid ~ /^PVPAM/) return "PvPAM";
    if (pid ~ /PvW1/ || pid ~ /PVW1/ || pid ~ /PVPVW/ || pid ~ /PVPV/) return "PvW1";
    return "unknown";
}
{
    rep=$1; member=$2; key=rep SUBSEP member;
    if (!(key in seen)) {
        seen[key]=1;
        size[rep]++;
        g=genome(member);
        count[rep,g]++;
    }
}
END {
    for (rep in size) {
        printf "%d\t%s\t%d\t%d\t%d\t%d\t%d\n", -size[rep], rep, size[rep]+0, count[rep,"PvP01"]+0, count[rep,"PvW1"]+0, count[rep,"PvPAM"]+0, count[rep,"unknown"]+0;
    }
}' vir_struct_cluster_cluster.tsv \
  | sort -k1,1n -k2,2 \
  | awk -F '\t' 'BEGIN { OFS="\t"; print "FS_cluster", "rep_id", "size", "PvP01", "PvW1", "PvPAM", "unknown" } { printf "FS_%03d\t%s\t%d\t%d\t%d\t%d\t%d\n", NR, $2, $3, $4, $5, $6, $7 }' \
  > foldseek_clusters_summary.tsv

ls -lh vir_struct_cluster* foldseek_clusters_summary.tsv >> foldseek.log 2>&1
'''

rep={
  "class":"GalaxyUserTool",
  "id":"anton-gpu-xl-foldseek_prostt5_clustering",
  "version":"1.0.5",
  "name":"Foldseek ProstT5 Structural Clustering (GPU XL, no Python summary)",
  "container":"quay.io/biocontainers/foldseek:10.941cd33",
  "description":"Run Foldseek easy-cluster with ProstT5-derived 3Di states using --gpu 1 and AWK summary generation.",
  "inputs":[
    {"name":"seqs","type":"data","label":"Combined VIR protein FASTA"},
    {"name":"prostt5_model","type":"data","label":"ProstT5 GGUF model file"},
    {"name":"coverage","type":"float","label":"Foldseek coverage threshold (-c)","value":0.8},
    {"name":"evalue","type":"float","label":"Foldseek E-value threshold (-e)","value":0.001},
    {"name":"alignment_type","type":"integer","label":"Foldseek alignment type","value":2},
    {"name":"threads","type":"integer","label":"Threads","value":32}
  ],
  "outputs":[
    {"name":"cluster_tsv","type":"data","format":"tabular","label":"Foldseek cluster assignments","from_work_dir":"vir_struct_cluster_cluster.tsv"},
    {"name":"rep_seq","type":"data","format":"fasta","label":"Foldseek representative sequences","from_work_dir":"vir_struct_cluster_rep_seq.fasta"},
    {"name":"all_seqs","type":"data","format":"fasta","label":"Foldseek clustered sequences FASTA","from_work_dir":"vir_struct_cluster_all_seqs.fasta"},
    {"name":"summary_tsv","type":"data","format":"tabular","label":"Foldseek cluster summary","from_work_dir":"foldseek_clusters_summary.tsv"},
    {"name":"log","type":"data","format":"txt","label":"Foldseek clustering log","from_work_dir":"foldseek.log"}
  ],
  "help":{"format":"markdown","content":"Runs Foldseek `easy-cluster` with a supplied ProstT5 GGUF model and explicit `--gpu 1`. Container identifier: `quay.io/biocontainers/foldseek:10.941cd33`. The post-processing summary uses awk/sort instead of Python because this Foldseek image does not include Python."},
  "shell_command": shell
}

r=requests.post(url+'/api/unprivileged_tools', headers=headers, json={'representation':rep}, timeout=60)
print('Register v1.0.5 status', r.status_code)
data=r.json()
print(json.dumps({k:data.get(k) for k in ['id','uuid','active','tool_id','create_time']}, indent=2))
print('version', data.get('representation',{}).get('version'))
print('container', data.get('representation',{}).get('container'))
uuid=data['uuid']

payload={
  'history_id':'bbd44e69cb8906b5c0a92f1d9b046fdd',
  'tool_uuid':uuid,
  'inputs':{
    'seqs': {'src':'hda','id':'f9cad7b01a472135280107cef6d12de2'},
    'prostt5_model': {'src':'hda','id':'f9cad7b01a472135dfae40ce8ed6d561'},
    'coverage': 0.8,
    'evalue': 0.001,
    'alignment_type': 2,
    'threads': 32
  }
}
r=requests.post(url+'/api/jobs', headers=headers, json=payload, timeout=120)
print('\nSubmit v1.0.5 status', r.status_code)
try:
    print(json.dumps(r.json(), indent=2)[:3000])
except Exception:
    print(r.text[:3000])
PY

