arguments.command:
cd /Users/anton/.loom/analyses/phist2
.loom/env/bin/python3 <<'PY'
import os,time
from bioblend.galaxy import GalaxyInstance

gi=GalaxyInstance(url=os.environ['GALAXY_URL'], key=os.environ['GALAXY_API_KEY'])
ids={142:'f9cad7b01a472135e9a4fbb4a5f7db60',143:'f9cad7b01a4721355988ce66d9f1ef6d',144:'f9cad7b01a4721350dfe5a1e0ab49395',145:'f9cad7b01a472135c5254ff7049392d2'}
terminal={'ok','error','discarded','deleted','failed_metadata'}
for poll in range(60):
    states=[]; jobs=set()
    print('\nPOLL', poll)
    try:
        for hid,did in ids.items():
            ds=gi.datasets.show_dataset(did)
            st=ds.get('state'); states.append(st)
            print(f"HID {hid}\t{st}\tsize={ds.get('file_size')}\t{ds.get('name')}\t{(ds.get('misc_info') or '')[:220]}")
            if ds.get('creating_job'): jobs.add(ds['creating_job'])
        for jid in jobs:
            job=gi.jobs.show_job(jid)
            print(f"JOB {jid}\t{job.get('state')}\texit={job.get('exit_code')}\texternal={job.get('external_id')}\tupdated={job.get('update_time')}")
        if all(s in terminal for s in states): break
    except Exception as e:
        print('poll_error', repr(e))
    time.sleep(60)
PY

