import os, json
from bioblend.galaxy import GalaxyInstance

gi=GalaxyInstance(url=os.environ['GALAXY_URL'], key=os.environ['GALAXY_API_KEY'])
jobs=['bbd44e69cb8906b5491b57586d37351c','bbd44e69cb8906b5e03132fc66b9d6cb']
for jid in jobs:
    print('\nJOB', jid)
    try:
        job=gi.jobs.show_job(jid, full_details=True)
    except TypeError:
        job=gi.jobs.show_job(jid)
    for k in ['id','state','exit_code','tool_id','tool_version','external_id','create_time','update_time','stderr','stdout']:
        v=job.get(k)
        if v is not None:
            s=str(v)
            print(k+':', s[:1200])
    print('outputs:', job.get('outputs'))

# inspect output states and previews for HIDs 217-228
hist='bbd44e69cb8906b5c0a92f1d9b046fdd'
contents=gi.histories.show_history(hist, contents=True)
byhid={int(d['hid']):d for d in contents if str(d.get('hid','')).isdigit()}
for hid in range(217,229):
    d=byhid.get(hid)
    if not d:
        print('missing hid',hid); continue
    ds=gi.datasets.show_dataset(d['id'])
    print('\nHID',hid,ds.get('id'),ds.get('state'),ds.get('name'),ds.get('file_size'),(ds.get('misc_info') or '')[:500])
    if ds.get('state') in ['ok','error'] and hid in [221,222,227,228]:
        try:
            txt=gi.datasets.show_dataset(d['id'], hda_ldda='hda').get('peek','')
            print('peek:',txt[:500])
        except Exception as e:
            print('peek_err',e)
